{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_632fdfa7d056c963cc65a5bb", "claim_ids": ["claim_92bfd2117a9195b81c5dd341", "claim_cddd97a8fab522fab8a18c54"], "query_ids": ["q_487"], "claims": [{"claim_id": "claim_92bfd2117a9195b81c5dd341", "quote": "The Commission’s public report, Active Anode Material from China(Inv. Nos. 701-TA-752 and 731-TA-1730 (Final), USITC Publication 5719, March 2026), will contain the views of the Commission and information developed during the investigations.", "url": "https://www.usitc.gov/press_room/news_release/2026/er0312_68281.htm", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Active Anode Material from China", "legal_authority": "Inv. Nos. 701-TA-752 and 731-TA-1730 (Final)", "affected_product": "active anode material"}}, {"claim_id": "claim_cddd97a8fab522fab8a18c54", "quote": "The U.S. International Trade Commission (Commission or USITC) today determined that imports of active anode material from China that the U.S. Department of Commerce (Commerce) has determined are sold in the United States at less than fair value and subsidized by the government of China have not materially retarded the establishment of an industry in the United States.", "url": "https://www.usitc.gov/press_room/news_release/2026/er0312_68281.htm", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "U.S. International Trade Commission", "tariff_program": "less than fair value and subsidized", "affected_product": "active anode material", "reported_policy_status": "not materially retarded the establishment of an industry in the United States"}}]}, {"pair_id": "conflict_34384fbd588f19d2f5f7f305", "claim_ids": ["claim_7a31e58fca072ced804e006e", "claim_908eff1e71305591162948b7"], "query_ids": ["q_488"], "claims": [{"claim_id": "claim_7a31e58fca072ced804e006e", "quote": "Twelve232 investigations launched—the most of any administration in history, including auto, lumber, pharmaceuticals, and semiconductors, to drive investments.", "url": "https://www.commerce.gov/news/press-releases/2026/01/first-year-accomplishments-under-secretary-howard-w-lutnick", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"affected_product": "auto"}}, {"claim_id": "claim_908eff1e71305591162948b7", "quote": "+ The U.S. Section 232 duties applied to Taiwanese auto parts, timber, lumber, and wood derivative products will total no more than 15 percent.", "url": "https://www.commerce.gov/news/fact-sheets/2026/01/fact-sheet-restoring-american-semiconductor-manufacturing-leadership", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "no more than 15 percent"}}]}, {"pair_id": "conflict_ad0e8d493cec816c51e1d5dd", "claim_ids": ["claim_17975eb0da262896b676d765", "claim_f7f65a312c7c27490c8dff18"], "query_ids": ["q_489"], "claims": [{"claim_id": "claim_17975eb0da262896b676d765", "quote": "Imports of derivative articles of aluminum, as referenced in Proclamation 9980,6 [...] under-use of the TRQ.", "url": "https://www.commerce.gov/sites/default/files/2021-10/US-232-EU-Statement.pdf", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"affected_product": "derivative articles of aluminum"}}, {"claim_id": "claim_f7f65a312c7c27490c8dff18", "quote": "Imports of derivative articles of steel, as referenced in Proclamation 9980,2 from the EU will not be subject to Section 232 duties.", "url": "https://www.commerce.gov/sites/default/files/2021-10/US-232-EU-Statement.pdf", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"affected_product": "derivative articles of steel"}}]}, {"pair_id": "conflict_da6b6c58713bf3ea75b23aa0", "claim_ids": ["claim_00aa4a18eb449df42503f441", "claim_b4fda96f7b0c71e72ec5b024"], "query_ids": ["q_490"], "claims": [{"claim_id": "claim_00aa4a18eb449df42503f441", "quote": "E&C is conducting technical reviews of the requests for product-specific exclusions from the Section 232 tariffs on imported steel and aluminum, for which U.S. producers submit objections.", "url": "http://www.commerce.gov/sites/default/files/2022-03/FY2023-ITA-Congressional-Budget-Submission.pdf", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "E&C", "tariff_program": "Section 232 tariffs", "affected_product": "steel and aluminum"}}, {"claim_id": "claim_b4fda96f7b0c71e72ec5b024", "quote": "Section 232: Aluminum Section 232: Steel Weather and satellites ・ 31 of the 35 minerals designated as critical ・ mineral criticality issues;", "url": "https://www.commerce.gov/data-and-reports/reports/2019/06/federal-strategy-ensure-secure-and-reliable-supplies-critical-minerals", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232", "affected_product": "Aluminum"}}]}, {"pair_id": "conflict_75697cf2102afee5f705b6ba", "claim_ids": ["claim_c38a543f3022f8105cdbc402", "claim_dbf83867435389a20f41cd7a"], "query_ids": ["q_491"], "claims": [{"claim_id": "claim_c38a543f3022f8105cdbc402", "quote": "the tariffs on automobile parts are set to go into effect on or after 12:01 a.m. eastern daylight time on May 3, 2025.", "url": "https://www.federalregister.gov/documents/2025/05/02/2025-07833/amendments-to-adjusting-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"effective_date": "May 3, 2025", "reported_policy_status": "set to go into effect"}}, {"claim_id": "claim_dbf83867435389a20f41cd7a", "quote": "The COVID-19 pandemic exposed critical vulnerabilities and choke points in global supply chains, undermining our ability to maintain a resilient domestic industrial base.", "url": "https://www.federalregister.gov/documents/2025/04/03/2025-05930/adjusting-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}]}, {"pair_id": "conflict_7fde466afec74a4d88b74fc9", "claim_ids": ["claim_0af9da4b347a0f5bf7833e75", "claim_0cde401cc86762603f82b6ee"], "query_ids": ["q_492"], "claims": [{"claim_id": "claim_0af9da4b347a0f5bf7833e75", "quote": "The U.S. Trade Representative initiated a product exclusion process in October 2019, and has issued eight product exclusion notices under this action.", "url": "https://www.federalregister.gov/documents/2020/09/02/2020-19419/notice-of-product-exclusion-extensions-chinas-acts-policies-and-practices-related-to-technology", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "product exclusion process"}}, {"claim_id": "claim_0cde401cc86762603f82b6ee", "quote": "The U.S. Trade Representative initiated a product exclusion process in June 2019, and interested persons have submitted requests for the exclusion of specific products.", "url": "https://public-inspection.federalregister.gov/2020-06276.pdf?1585140334=", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"legal_authority": "sections 301(b), 301(c), and 307(a) of the Trade Act of 1974", "effective_date": "September 24, 2018", "expiration_date": "August 7, 2020"}}]}, {"pair_id": "conflict_3a2d6443d08b3b8d10751ae1", "claim_ids": ["claim_0af9da4b347a0f5bf7833e75", "claim_a87f2c4302cb26f7ae01059b"], "query_ids": ["q_492"], "claims": [{"claim_id": "claim_0af9da4b347a0f5bf7833e75", "quote": "The U.S. Trade Representative initiated a product exclusion process in October 2019, and has issued eight product exclusion notices under this action.", "url": "https://www.federalregister.gov/documents/2020/09/02/2020-19419/notice-of-product-exclusion-extensions-chinas-acts-policies-and-practices-related-to-technology", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "product exclusion process"}}, {"claim_id": "claim_a87f2c4302cb26f7ae01059b", "quote": "The U.S. Trade Representative initiated a product exclusion process in June 2019, and interested persons have submitted requests for the exclusion of specific products.", "url": "https://www.federalregister.gov/documents/2020/02/20/2020-03377/notice-of-product-exclusions-chinas-acts-policies-and-practices-related-to-technology-transfer", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "product exclusion process", "announcement_date": "June 2019"}}]}, {"pair_id": "conflict_39e8f93b712f137017a706e4", "claim_ids": ["claim_1c777665def866b0c3570fe9", "claim_87997eded7c44b82ba373c92"], "query_ids": ["q_494"], "claims": [{"claim_id": "claim_1c777665def866b0c3570fe9", "quote": "The petitioner is the American Active Anode Material Producers, which is an ad hoc coalition comprised of Anovion Technologies (Sanborn, NY), Syrah Technologies LLC (Vidalia, LA), NOVONIX Anode Materials LLC (Chattanooga, TN), Epsilon Advanced Materials (Leland, NC), and SKI US, Inc. (Marietta, GA).", "url": "https://www.trade.gov/preliminary-affirmative-determination-antidumping-duty-investigation-active-anode-material-0", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "SKI US, Inc."}}, {"claim_id": "claim_87997eded7c44b82ba373c92", "quote": "SKI US, Inc. (Marietta, GA)", "url": "https://www.trade.gov/preliminary-determinations-countervailing-duty-investigations-active-anode-material-china", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "SKI US, Inc."}}]}, {"pair_id": "conflict_b79c6b8eef364838c5bc9194", "claim_ids": ["claim_1c777665def866b0c3570fe9", "claim_ab86366bee851de021b1bc85"], "query_ids": ["q_494"], "claims": [{"claim_id": "claim_1c777665def866b0c3570fe9", "quote": "The petitioner is the American Active Anode Material Producers, which is an ad hoc coalition comprised of Anovion Technologies (Sanborn, NY), Syrah Technologies LLC (Vidalia, LA), NOVONIX Anode Materials LLC (Chattanooga, TN), Epsilon Advanced Materials (Leland, NC), and SKI US, Inc. (Marietta, GA).", "url": "https://www.trade.gov/preliminary-affirmative-determination-antidumping-duty-investigation-active-anode-material-0", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "SKI US, Inc."}}, {"claim_id": "claim_ab86366bee851de021b1bc85", "quote": "The petitioner is the American Active Anode Material Producers, which is an ad hoc coalition comprised of Anovion Technologies (Sanborn, NY), Syrah Technologies LLC (Vidalia, LA), NOVONIX Anode Materials LLC (Chattanooga, TN), Epsilon Advanced Materials (Leland, NC), and SKI US, Inc. (Marietta, GA).", "url": "https://www.trade.gov/preliminary-affirmative-determination-antidumping-duty-investigation-active-anode-material-0", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "American Active Anode Material Producers"}}]}, {"pair_id": "conflict_6e7b0f367fb58f784744dc71", "claim_ids": ["claim_1c777665def866b0c3570fe9", "claim_c8fb3878e3eea36a23293fb9"], "query_ids": ["q_494"], "claims": [{"claim_id": "claim_1c777665def866b0c3570fe9", "quote": "The petitioner is the American Active Anode Material Producers, which is an ad hoc coalition comprised of Anovion Technologies (Sanborn, NY), Syrah Technologies LLC (Vidalia, LA), NOVONIX Anode Materials LLC (Chattanooga, TN), Epsilon Advanced Materials (Leland, NC), and SKI US, Inc. (Marietta, GA).", "url": "https://www.trade.gov/preliminary-affirmative-determination-antidumping-duty-investigation-active-anode-material-0", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "SKI US, Inc."}}, {"claim_id": "claim_c8fb3878e3eea36a23293fb9", "quote": "The petitioner is the American Active Anode Material Producers, which is an ad hoc coalition comprised of Anovion Technologies 